from pathlib import Path
import json
A=Path(__file__).resolve().parent
R=A.parents[1]
C=A.parent
manifest=json.loads((A/'candidate-manifest.json').read_text())
active=json.loads((R/'active.json').read_text())
rows=[]
for phase in ('3','6A','6B','9','12'):
    d=next(x for x in manifest['phases'] if x['phase']==phase)
    folder=R/active['scene_folders'][phase]
    def url(p):return '/game/art/'+str(p.relative_to(R.parent))
    d['whole']=url(folder/('complete-closed-objectives.png' if phase=='6B' else 'complete-native.png'))
    d['source']=url(folder/'manifest.json')
    d['states']=[]
    for label,name in [('Igreja destruída','complete-damaged-native.png'),('Portões abertos','complete-open-objectives.png'),('Colapso','complete-collapse-objectives.png')]:
        if (folder/name).exists():d['states'].append({'label':label,'path':url(folder/name)})
    rows.append(d)
html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Plaguefall · Correção dos corredores</title><style>
*{box-sizing:border-box}body{margin:0;background:#171b1d;color:#e5e1d6;font:16px/1.5 system-ui}main{max-width:1360px;margin:auto;padding:32px}h1{font-size:30px;margin:8px 0}h2{font-size:23px}a{color:#b9d6cb}nav{display:flex;gap:8px;position:sticky;top:0;background:#171b1df5;padding:12px 0;z-index:2}button{padding:10px 18px;color:inherit;background:#2d3537;border:1px solid #697274;border-radius:4px;cursor:pointer}button.selected{background:#496359}.muted,figcaption{color:#aeb8b4;font-size:13px}.status{padding:16px;background:#353023;border-left:4px solid #c5a970}code{font-size:11px;overflow-wrap:anywhere}.whole{width:100%;height:auto;image-rendering:pixelated;background:#101416}.cams{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px}figure{margin:0}figure img{display:block;width:100%;image-rendering:pixelated}table{border-collapse:collapse;width:100%;margin:18px 0}td,th{text-align:left;padding:8px;border-bottom:1px solid #3c4546}.full{overflow:auto}.full img{max-width:none;image-rendering:pixelated}.links{display:flex;gap:18px;flex-wrap:wrap}details{margin:20px 0}summary{cursor:pointer}.reference{display:flex;gap:16px;flex-wrap:wrap}.reference img{max-width:320px;image-rendering:pixelated}</style><main>
<p class="muted">Guia de produção e storyboard · cenário nativo · comparação no jogo</p><h1>Correção dos corredores</h1><p>Reutilização do kit existente, arquitetura completa e revisão do percurso inteiro. Fases 3, 6A, 6B, 9 e 12; as outras 14 composições foram preservadas.</p><div class="status" id="status">Candidata em validação. Arte, objetivos e desempenho têm verificações separadas.</div><p class="links"><a href="../../../../../../out/release/Plaguefall.bin" id="rom" hidden>ROM da campanha</a><a href="../contract.json">Critérios da correção</a><a href="../reviews/candidate-family-audit.json">Parecer visual</a><a href="acceptance.json">Resultados desta versão</a></p><code id="sha"></code><nav id="nav"></nav><h2 id="title"></h2><p id="change"></p><table id="metrics"></table><h3>Cenário inteiro</h3><p class="muted">A visão inteira permite avaliar ritmo e continuidade; as imagens abaixo mostram a escala real e a câmera do jogo.</p><img class="whole" id="whole"><p class="links" id="states"></p><details><summary>Inspecionar panorama em 1×</summary><div class="full"><img id="native"></div></details><h3>Câmeras reais da ROM</h3><p class="muted">Enquadramentos legais para inspecionar os marcos. Combate e progresso são suspensos nessas capturas; testes de movimento e carga estão separados.</p><div class="cams" id="cams"></div><details><summary>Varredura real do campo: todos os intervalos</summary><div class="cams" id="sweep"></div></details><p><a id="source">Fontes e geometria desta fase</a></p><details><summary>Referências do guia</summary><div class="reference"><figure><img src="/game/art/phase01-courtyard-v2/intact-native.png"><figcaption>Pátio: projeção, escala e materiais existentes.</figcaption></figure><figure><img src="/game/art/phase04-tunnels-v1/map-native.png"><figcaption>Galerias: concreto, carvão e ferrugem.</figcaption></figure></div></details><p class="muted">FPS mede atualizações de simulação por VBlank no emulador, com movimento, população e pools de tiros declarados. Hardware físico e dificuldade humana não são atestados por esses testes.</p></main><script>
const phases=PHASES,sha=SHA,el=id=>document.getElementById(id);let region='ntsc',selected=location.hash.slice(2)||'9',captures={},acceptance={};
const descriptions={'3':'Igreja original nos dois estados, rua com mercado, casas, oficinas e acesso ao galpão. Materiais e projeção voltam à família do pátio.','6A':'Concreto e carvão do kit das galerias; bombas e manutenção nos intervalos. Geometria e escolta preservadas.','6B':'Mesmo kit dos esgotos, com duas válvulas e portões; todos os estados de abertura compartilham o limite de memória.','9':'Rua industrial de 2560 px com oficinas, doca, dois galpões maiores e veículos do kit existente. A porta final é a mesma da fábrica das fases 10 e 11.','12':'Coberturas dominantes e fachadas curtas nas oficinas e anexos; metal no estaleiro e sindicato reconhecível. Escolta e ramificação 13A/13B preservadas.'};
async function get(p){try{let r=await fetch(p);return r.ok?await r.json():null}catch{return null}}
function picture(s,base){let f=document.createElement('figure'),im=document.createElement('img'),c=document.createElement('figcaption');im.loading='lazy';im.src=base+s.path;c.textContent=s.label+' · câmera '+s.camera.join(', ');f.append(im,c);return f}
function show(){let d=phases.find(x=>x.phase===selected)||phases[0];selected=d.phase;location.hash='p'+selected;el('title').textContent='Fase '+selected;el('change').textContent=descriptions[selected];el('whole').src=d.whole;el('native').src=d.whole;el('source').href=d.source;el('states').replaceChildren();for(let s of d.states){let a=document.createElement('a');a.href=s.path;a.textContent=s.label;el('states').append(a)}el('cams').replaceChildren();el('sweep').replaceChildren();let cap=captures[region]?.phases?.find(x=>x.phase===selected);for(let s of cap?.samples||[]){if(s.row===3)el('cams').append(picture(s,'captures/'+region+'/'));else if(s.row===1)el('sweep').append(picture(s,'captures/'+region+'/'))}let perf=acceptance.performance?.[selected]||{},capEnemies=selected==='3'?4:3,shots=selected==='3'?6:4;el('metrics').innerHTML='<tr><th>Inimigos ativos na carga</th><td>'+capEnemies+'</td><th>Tiros por pool</th><td>'+shots+'</td></tr><tr><th>FPS NTSC / PAL</th><td>'+(perf.ntsc?.gameFPS??'em medição')+' / '+(perf.pal?.gameFPS??'em medição')+'</td><th>Tiles residentes /640</th><td>'+d.memory.total_tiles+'</td></tr>';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.phase===selected))}
(async()=>{[captures.ntsc,captures.pal,acceptance]=await Promise.all(['captures/ntsc/capture-report.json','captures/pal/capture-report.json','acceptance.json'].map(get));acceptance=acceptance||{};for(let r of ['ntsc','pal'])if(captures[r]?.rom_sha256!==sha)captures[r]=null;if(acceptance.rom_sha256!==sha)acceptance={};el('sha').textContent='ROM SHA256: '+sha;el('status').textContent=acceptance.user_status||'Candidata em validação; aprovação final pendente.';for(let d of phases){let b=document.createElement('button');b.textContent=d.phase;b.dataset.phase=d.phase;b.onclick=()=>{selected=d.phase;show()};el('nav').append(b)}let b=document.createElement('button');b.textContent='Câmeras PAL';b.onclick=()=>{region=region==='ntsc'?'pal':'ntsc';b.textContent=region==='ntsc'?'Câmeras PAL':'Câmeras NTSC';show()};el('nav').append(b);if(acceptance.production_rom_matches){el('rom').href='/game/out/release/Plaguefall.bin';el('rom').hidden=false}show()})()
</script></html>'''.replace('PHASES',json.dumps(rows,ensure_ascii=False)).replace('SHA,','"'+manifest['rom_sha256']+'",')
